test("production: APP_CACHE__TTL_SECONDS overrides the file", () => {
  const cfg = loadConfig({ env: { APP_ENV: "production", APP_CACHE__TTL_SECONDS: "60" }, file: { cache: { ttlSeconds: 600 } } });
  assert.equal(cfg.cache.ttlSeconds, 60);
});

test("production: non-allowlisted nested env vars do not override the file", () => {
  const cfg = loadConfig({ env: { APP_ENV: "production", APP_CACHE__REDIS__HOST: "stale.internal" }, file: { cache: { redis: { host: "redis.internal" } } } });
  assert.equal(cfg.cache.redis.host, "redis.internal");
});
